package br.com.lealinfo.vidraceiro;
import android.content.*;import android.os.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.concurrent.*;
/** Durable optimistic outbox. All business/store mutations stay on the Activity main thread. */
final class SyncCoordinator {
 final MainActivity a;final ProfessionalStore store;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();final AtomicFile stateFile;JSONObject state;boolean busy,closed;SyncTransport.Exchange transport=SyncTransport.HTTPS;
 final Runnable tickJob=this::tick;
 static final String[] ENTITIES={"clients","materials","projects"};
 SyncCoordinator(MainActivity a,ProfessionalStore store)throws Exception{this.a=a;this.store=store;stateFile=new AtomicFile(new File(a.getFilesDir(),"pdv-sync-state.json"));state=stateFile.getBaseFile().exists()||new File(stateFile.getBaseFile()+".bak").exists()?new JSONObject(new String(stateFile.readFully(),StandardCharsets.UTF_8)):new JSONObject().put("links",new JSONObject()).put("tenant","");if(state.optBoolean("detachConfirmed"))finishDetach();if(state.has("switchTo"))finishActivation();main.postDelayed(tickJob,1200);}
 void save()throws Exception{byte[] b=state.toString().getBytes(StandardCharsets.UTF_8);FileOutputStream out=null;try{out=stateFile.startWrite();out.write(b);stateFile.finishWrite(out);}catch(Exception e){if(out!=null)stateFile.failWrite(out);throw e;}}
 JSONObject links()throws Exception{return state.getJSONObject("links");}
 JSONObject link(String entity,String id)throws Exception{String key=entity+"/"+id;JSONObject l=links().optJSONObject(key);if(l==null){l=new JSONObject().put("revision",0).put("baseline",JSONObject.NULL);links().put(key,l);}return l;}
 static JSONObject business(String entity,JSONObject src)throws Exception{JSONObject p=new JSONObject(src.toString());for(String key:new String[]{"id","pdvId","syncState","revision","createdAt","updatedAt","legacySource","_sync"})p.remove(key);if(entity.equals("clients")||entity.equals("suppliers")){JSONObject clean=new JSONObject();for(String key:new String[]{"name","document","phone","email","address","cep","street","number","complement","district","city","uf"})if(p.has(key))clean.put(key,p.optString(key));return clean;}if(entity.equals("projects")){JSONObject budget=p.optJSONObject("budget");if(budget!=null)for(String k:new String[]{"price","service","discount","extra"})if(budget.has(k))budget.put(k,Commercial.amount(budget.optString(k)).stripTrailingZeros().toPlainString());}return p;}
 static String canonical(Object o)throws Exception{if(o instanceof JSONObject){JSONObject j=(JSONObject)o;ArrayList<String> keys=new ArrayList<>();j.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys)b.append(JSONObject.quote(k)).append(':').append(canonical(j.get(k))).append(',');return b.append('}').toString();}if(o instanceof JSONArray){StringBuilder b=new StringBuilder("[");JSONArray ar=(JSONArray)o;for(int i=0;i<ar.length();i++)b.append(canonical(ar.get(i))).append(',');return b.append(']').toString();}return o instanceof String?JSONObject.quote((String)o):String.valueOf(o);}
 static boolean equal(JSONObject a,JSONObject b)throws Exception{return a!=null&&b!=null&&canonical(a).equals(canonical(b));}
 String status(){if(state.optBoolean("detaching"))return "DESVINCULAÇÃO PENDENTE\n"+(busy?"Aguarde a confirmação do servidor.":"Sem confirmação do servidor. Toque em DESVINCULAR PDV para tentar novamente. Seus dados estão preservados.");if(busy&&state.optString("tenant").isEmpty())return "CONECTANDO AO PDV…\nAguarde a confirmação do servidor.";if(state.optBoolean("revoked"))return "DESCONECTADO — vínculo revogado no PDV.\nToque em DESVINCULAR PDV e use um novo código para conectar novamente.";String tenant=state.optString("tenant");if(!tenant.isEmpty()&&state.optBoolean("bindingOnly"))return state.optString("error").isEmpty()?"CONECTADO • "+state.optString("name")+"\nVinculação por código ativa.":"DESCONECTADO / SEM COMUNICAÇÃO\n"+state.optString("error");if(tenant.isEmpty())return "NÃO VINCULADO\nConecte uma vez usando o código mostrado no computador.";int pending=0,conflicts=0,errors=0;String details="";JSONObject links=state.optJSONObject("links");if(links!=null){Iterator<String> it=links.keys();while(it.hasNext()){JSONObject l=links.optJSONObject(it.next());if(l.has("pending"))pending++;if(l.has("conflict"))conflicts++;if(!l.optString("error").isEmpty()){errors++;if(details.isEmpty())details="\nRevisar dados: "+l.optString("error");}}}int awaiting=0;try{for(String entity:ENTITIES){if(entity.equals("materials"))continue;JSONArray records=store.list(entity);for(int i=0;i<records.length();i++){JSONObject local=records.getJSONObject(i),l=links.optJSONObject(entity+"/"+local.getString("id"));if(entity.equals("projects")&&(l==null||!l.has("pending")&&!l.has("approvedPayload"))){if(l!=null&&l.optLong("revision")>0&&local.isNull("pdvId"))awaiting++;continue;}if(l==null){pending++;continue;}if(!l.has("pending")&&!l.has("conflict")&&!equal(business(entity,local),l.optJSONObject("baseline")))pending++;if(l.optLong("revision")>0&&local.isNull("pdvId"))awaiting++;}}}catch(Exception ignored){}String date=state.optLong("lastSuccess")==0?"Ainda não realizada":new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm:ss",new Locale("pt","BR")).format(new Date(state.optLong("lastSuccess")));long pdvSeen=state.optLong("pdvLastSeen");return "PDV: "+state.optString("name","Conectado")+"\n"+(busy?"SINCRONIZANDO":state.optString("error").isEmpty()?"CONECTADO":"OFFLINE / SINCRONIZAÇÃO PENDENTE")+"\nÚltima sincronização: "+date+"\nPendentes: "+pending+" • Conflitos: "+conflicts+" • Erros: "+errors+details+"\nAguardando confirmação do PDV: "+awaiting+"\n"+(pdvSeen>0?"Último contato do PDV: "+new java.text.SimpleDateFormat("dd/MM HH:mm",new Locale("pt","BR")).format(new Date(pdvSeen)):"Aguardando primeiro contato do PDV.")+(state.optBoolean("photoPending")?"\nAnexo pendente de transferência.":"")+(state.optString("error").isEmpty()?"":"\n"+state.optString("error"));}
 void notifyUi(){if(a.syncRefresh!=null)a.syncRefresh.run();}
 AtomicFile profile(String tenant)throws Exception{return new AtomicFile(new File(a.getFilesDir(),"pdv-profiles/"+SecureGateway.hash(tenant.getBytes(StandardCharsets.UTF_8))+".json"));}
 static void writeJson(AtomicFile file,JSONObject data)throws Exception{File parent=file.getBaseFile().getParentFile();if(!parent.exists()&&!parent.mkdirs())throw new IOException("Não foi possível preservar os dados do PDV.");FileOutputStream out=null;try{out=file.startWrite();out.write(data.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
 void archive()throws Exception{String tenant=state.optString("tenant");if(tenant.isEmpty())return;writeJson(profile(tenant),new JSONObject().put("tenant",tenant).put("state",new JSONObject(state.toString())).put("data",new JSONObject(store.data.toString())));}
 void clearSelection(){a.saveScreen=null;a.current=null;a.getPreferences(0).edit().remove("professionalCurrent").remove("photoTargetProject").remove("photoTargetWorkspace").commit();}
 void finishDetach()throws Exception{clearSelection();store.data=emptyData();store.fingerprints.clear();store.save();JSONObject cleared=new JSONObject().put("links",new JSONObject()).put("tenant","");writeJson(stateFile,cleared);state=cleared;}
 static JSONObject emptyData()throws Exception{return new JSONObject().put("schemaVersion",2).put("workspace",SecureGateway.hash(UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8))).put("legacyImported",true).put("projects",new JSONArray()).put("clients",new JSONArray()).put("materials",new JSONArray()).put("suppliers",new JSONArray());}
 void finishActivation()throws Exception{JSONObject result=state.getJSONObject("switchTo"),data=state.getJSONObject("activationData");String tenant=result.getString("tenant");JSONObject restored=new JSONObject().put("links",new JSONObject());AtomicFile file=profile(tenant);if(file.getBaseFile().exists()||new File(file.getBaseFile()+".bak").exists()){JSONObject snapshot=new JSONObject(new String(file.readFully(),StandardCharsets.UTF_8));if(!tenant.equals(snapshot.getString("tenant")))throw new IOException("Dados de outro PDV recusados.");restored=snapshot.getJSONObject("state");data=snapshot.getJSONObject("data");}clearSelection();store.data=new JSONObject(data.toString());store.fingerprints.clear();store.save();for(String key:new String[]{"detaching","detachConfirmed","switchTo","activationData"})restored.remove(key);JSONObject activated=restored.put("tenant",tenant).put("name",result.optString("name")).put("error","").put("revoked",false).put("bindingOnly",result.optBoolean("bindingOnly"));writeJson(stateFile,activated);state=activated;}
 void confirmUnlink(){if(busy){a.message("Aguarde a operação em andamento e tente novamente.");return;}if(state.optString("tenant").isEmpty())return;new InteriorVisuals.Dialog(a).setTitle("Desvincular PDV?").setMessage("Desconectar este celular de "+state.optString("name","PDV")+"? O computador não precisa estar ligado. Projetos, cadastros e pendências serão guardados separadamente para este PDV e não serão enviados ao próximo. É necessário acesso à internet para confirmar a revogação.").setNegativeButton("CANCELAR",null).setPositiveButton("DESVINCULAR",(d,w)->a.run(this::unlink)).show();}
 void unlink()throws Exception{if(busy||state.optString("tenant").isEmpty())return;if(state.optBoolean("detachConfirmed")){finishDetach();a.integration();return;}a.flush();archive();state.put("detaching",true);save();busy=true;notifyUi();worker.execute(()->{try{JSONObject result=transport.call("/sync/unlink",new JSONObject());if(!result.optBoolean("revoked"))throw new IOException("O servidor não confirmou a desvinculação.");main.post(()->{if(closed)return;try{state.put("detachConfirmed",true);save();finishDetach();busy=false;a.integration();}catch(Exception e){failed(e);}});}catch(Exception e){main.post(()->{if(!closed)failed(e);});}});}
 void connect(String code){if(busy)return;if(!state.optString("tenant").isEmpty()){a.message("Desvincule o PDV atual antes de informar um novo código.");return;}busy=true;notifyUi();worker.execute(()->{try{SyncTransport.register();JSONObject result=transport.call("/sync/pair",new JSONObject().put("code",code.trim().replace(" ","").toUpperCase(Locale.ROOT)));main.post(()->{if(closed)return;try{state.put("switchTo",result).put("activationData",new JSONObject(store.data.toString()));save();finishActivation();busy=false;a.integration();tick();}catch(Exception e){failed(e);}});}catch(Exception e){main.post(()->{if(!closed)failed(e);});}});}
 String deliveryStatus(JSONObject project){try{if(state.optString("tenant").isEmpty()||state.optBoolean("revoked")||state.optBoolean("detaching"))return "PENDENTE — conecte ao PDV para enviar";JSONObject l=links().optJSONObject("projects/"+project.getString("id"));if((l==null||!l.has("pending")&&!l.has("approvedPayload")&&!l.has("conflict")&&l.optString("error").isEmpty())&&(l==null||!equal(business("projects",project),l.optJSONObject("baseline"))))return "RASCUNHO — toque em ENVIAR PARA O PDV";if(l==null||l.has("pending")||l.has("conflict")||!l.optString("error").isEmpty()||!equal(business("projects",project),l.optJSONObject("baseline")))return "PENDENTE";JSONObject photo=project.optJSONObject("photoAttachment");if(photo!=null&&!photo.optString("sha256").equals(l.optString("photoDone")))return "PENDENTE — enviando foto";return l.optBoolean("receivedByPdv")&&!project.isNull("pdvId")?"RECEBIDO — disponível na Central de Vidraçaria":"ENVIADO — aguardando recebimento pelo PDV";}catch(Exception e){return "PENDENTE";}}
 JSONObject projectPayload(JSONObject local)throws Exception{JSONObject payload=business("projects",local);JSONArray drafts=new JSONArray(),ids=local.optJSONArray("materialLocalIds");for(int j=0;ids!=null&&j<ids.length();j++){JSONObject m=store.find("materials",ids.optString(j));if(m!=null&&m.isNull("pdvId"))drafts.put(new JSONObject().put("id",m.getString("id")).put("name",m.optString("name")).put("specification",m.optString("specification")));}if(drafts.length()>0){payload.put("materialDrafts",drafts);local.put("materialDrafts",new JSONArray(drafts.toString()));}else{payload.remove("materialDrafts");local.remove("materialDrafts");}return payload;}
 void sendProject(JSONObject project)throws Exception{if(state.optString("tenant").isEmpty()||state.optBoolean("revoked")||state.optBoolean("detaching"))throw new IOException("Conecte ao PDV antes de enviar o projeto.");a.flush();a.validateProject(project);JSONObject approved=projectPayload(project),photo=approved.optJSONObject("photoAttachment");if(photo!=null){String sha=photo.getString("sha256");if(!sha.matches("[a-f0-9]{64}"))throw new IOException("Foto inválida.");File dir=PhotoAttachment.directory(a,project),source=new File(dir,"photo.jpg");if(!source.exists()||!SecureGateway.hash(Files.readAllBytes(source.toPath())).equals(sha))throw new IOException("Confira a foto antes de enviar.");Files.copy(source.toPath(),new File(dir,"approved-"+sha+".jpg").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}link("projects",project.getString("id")).put("approvedPayload",approved);store.save();save();prepare();notifyUi();tick();}
 void failed(Exception e){busy=false;try{if(e.getMessage()!=null&&e.getMessage().contains("vínculo revogado no PDV"))state.put("revoked",true);state.put("error",e.getMessage()==null?"Conexão indisponível; dados preservados.":e.getMessage());save();}catch(Exception ignored){}notifyUi();}
 void tick(){if(closed)return;main.removeCallbacks(tickJob);main.postDelayed(tickJob,5000);if(busy||state.optBoolean("detaching")||state.has("switchTo")||state.optString("tenant").isEmpty()||state.optBoolean("revoked"))return;if(state.optBoolean("bindingOnly")){busy=true;worker.execute(()->{try{JSONObject response=transport.call("/sync/status",new JSONObject());main.post(()->{if(closed)return;try{if(!state.optString("tenant").equals(response.getString("tenant")))throw new IOException("Resposta de outro PDV recusada.");state.put("error","").put("bindingOnly",response.optBoolean("bindingOnly"));save();busy=false;notifyUi();if(!state.optBoolean("bindingOnly"))tick();}catch(Exception e){failed(e);}});}catch(Exception e){main.post(()->{if(!closed)failed(e);});}});return;}try{a.flush();JSONArray changes=prepare();busy=true;notifyUi();worker.execute(()->exchange(changes,null));}catch(Exception e){failed(e);}}
 JSONArray prepare()throws Exception{JSONArray out=new JSONArray();int bytes=0;for(String entity:ENTITIES){if(entity.equals("materials"))continue;JSONArray list=store.list(entity);for(int i=0;i<list.length();i++){JSONObject local=list.getJSONObject(i);JSONObject l=link(entity,local.getString("id")),payload;if(l.has("conflict"))continue;try{if(entity.equals("projects")){JSONObject approved=l.optJSONObject("approvedPayload"),queued=l.optJSONObject("pending");if(approved==null&&queued!=null)approved=queued.optJSONObject("payload");if(approved==null)continue;payload=new JSONObject(approved.toString());}else payload=business(entity,local);}catch(Exception invalid){l.put("error",invalid.getMessage());continue;}if(entity.equals("projects")){try{a.validateProject(payload);}catch(Exception invalid){continue;}}
JSONObject base=l.optJSONObject("baseline"),pending=l.optJSONObject("pending");if(entity.equals("projects")&&pending==null&&equal(base,payload))l.remove("approvedPayload");if(pending==null&&!equal(base,payload)){pending=new JSONObject().put("entity",entity).put("id",local.getString("id")).put("operationId",UUID.randomUUID().toString()).put("baseRevision",l.optLong("revision")).put("payload",payload);l.put("pending",pending);}
  if(pending!=null&&out.length()<20&&bytes+pending.toString().length()<3000000){out.put(new JSONObject(pending.toString()));bytes+=pending.toString().length();}
 }}store.save();save();return out;}
 void exchange(JSONArray changes,String cursor){try{JSONObject response=transport.call("/sync/exchange",new JSONObject().put("changes",changes).put("cursor",cursor==null?JSONObject.NULL:cursor));main.post(()->{if(closed||state.optBoolean("detaching"))return;try{if(!state.getString("tenant").equals(response.getString("tenant")))throw new IOException("Resposta de outro PDV recusada.");apply(response);String next=response.optString("cursor","");if(!next.isEmpty()&&!next.equals("null")){worker.execute(()->exchange(new JSONArray(),next));return;}state.put("lastSuccess",System.currentTimeMillis()).put("pdvLastSeen",response.optLong("pdvLastSeen")).put("error","");store.save();save();busy=false;notifyUi();photos();}catch(Exception e){failed(e);}});}catch(Exception e){main.post(()->{if(!closed)failed(e);});}}
 void apply(JSONObject response)throws Exception{JSONArray results=response.optJSONArray("results");for(int i=0;results!=null&&i<results.length();i++){JSONObject result=results.getJSONObject(i);String entity=result.optString("entity"),id=result.optString("id");JSONObject l=link(entity,id);if(result.optBoolean("ok")){JSONObject rec=result.getJSONObject("record");l.put("receivedByPdv",rec.optBoolean("receivedByPdv")).put("baseline",new JSONObject(rec.getJSONObject("payload").toString())).put("revision",rec.getLong("revision"));l.remove("pending");if(entity.equals("projects")&&equal(l.optJSONObject("approvedPayload"),rec.getJSONObject("payload")))l.remove("approvedPayload");l.remove("error");JSONObject local=store.find(entity,id);if(local!=null){local.put("pdvId",rec.opt("officialId")).put("syncState","SYNCHRONIZED");}}else if(result.optBoolean("conflict")){l.put("conflict",result.opt("record"));}else l.put("error",result.optString("error","Dados pendentes de revisão."));}
 JSONArray records=response.optJSONArray("records");for(int i=0;records!=null&&i<records.length();i++){JSONObject rec=records.getJSONObject(i);String entity=rec.getString("entity"),id=rec.getString("id");if(!Arrays.asList(ENTITIES).contains(entity))continue;JSONObject l=link(entity,id),local=store.find(entity,id),remote=rec.getJSONObject("payload");if(rec.getLong("revision")<=l.optLong("revision")){if(rec.getLong("revision")==l.optLong("revision")&&local!=null&&equal(business(entity,local),remote))l.put("receivedByPdv",rec.optBoolean("receivedByPdv"));continue;}JSONObject base=l.optJSONObject("baseline");if(local!=null&&!equal(business(entity,local),base)&&!equal(business(entity,local),remote)){l.put("conflict",rec);continue;}if(local==null){local=new JSONObject().put("id",id);store.list(entity).put(local);}replace(local,remote,entity,id,rec.opt("officialId"));l.put("receivedByPdv",rec.optBoolean("receivedByPdv")).put("baseline",new JSONObject(remote.toString())).put("revision",rec.getLong("revision"));l.remove("pending");l.remove("conflict");l.remove("error");}
 store.save();save();notifyUi();}
 static void replace(JSONObject local,JSONObject payload,String entity,String id,Object official)throws Exception{ArrayList<String> keys=new ArrayList<>();local.keys().forEachRemaining(keys::add);for(String k:keys)if(!Arrays.asList("id","pdvId","syncState","revision","createdAt","updatedAt").contains(k))local.remove(k);Iterator<String> it=payload.keys();while(it.hasNext()){String key=it.next();local.put(key,payload.get(key));}local.put("id",id).put("pdvId",official==null?JSONObject.NULL:official).put("syncState","SYNCHRONIZED");}
 void conflicts(){try{ArrayList<String> ids=new ArrayList<>(),names=new ArrayList<>();Iterator<String> it=links().keys();while(it.hasNext()){String k=it.next();JSONObject l=links().getJSONObject(k);if(l.has("conflict")&&!l.isNull("conflict")){ids.add(k);JSONObject r=l.getJSONObject("conflict");names.add(r.getJSONObject("payload").optString("name",r.getJSONObject("payload").optString("title",k)));}}if(ids.isEmpty()){a.message("Nenhum conflito pendente.\n"+status());return;}new InteriorVisuals.Dialog(a).setTitle("Revisar alterações concorrentes").setItems(names.toArray(new String[0]),(d,n)->{String k=ids.get(n);a.run(()->{JSONObject l=links().getJSONObject(k),rec=l.getJSONObject("conflict");String[] parts=k.split("/",2);JSONObject local=store.find(parts[0],parts[1]);new InteriorVisuals.Dialog(a).setTitle(names.get(n)).setMessage("As duas versões foram preservadas. Escolha explicitamente qual deve continuar.\n\nLOCAL:\n"+business(parts[0],local).toString(2)+"\n\nPDV/SERVIDOR:\n"+rec.getJSONObject("payload").toString(2)).setPositiveButton("MANTER LOCAL",(x,w)->a.run(()->resolve(k,false))).setNeutralButton("USAR SERVIDOR",(x,w)->a.run(()->resolve(k,true))).setNegativeButton("VOLTAR",null).show();});}).show();}catch(Exception e){a.message(e.getMessage());}}
 void resolve(String key,boolean useRemote)throws Exception{JSONObject l=links().getJSONObject(key),rec=l.getJSONObject("conflict");String[] p=key.split("/",2);JSONObject local=store.find(p[0],p[1]);JSONArray archive=state.optJSONArray("conflictArchive");if(archive==null){archive=new JSONArray();state.put("conflictArchive",archive);}archive.put(new JSONObject().put("at",System.currentTimeMillis()).put("entity",p[0]).put("id",p[1]).put("local",business(p[0],local)).put("remote",rec));if(useRemote)replace(local,rec.getJSONObject("payload"),p[0],p[1],rec.opt("officialId"));l.put("baseline",rec.getJSONObject("payload")).put("revision",rec.getLong("revision"));l.remove("pending");l.remove("conflict");store.save();save();notifyUi();tick();}
 void photos(){ArrayList<JSONObject> tasks=new ArrayList<>();try{JSONArray p=store.list("projects");for(int i=0;i<p.length();i++){JSONObject project=p.getJSONObject(i),l=link("projects",project.getString("id")),base=l.optJSONObject("baseline"),manifest=base==null?null:base.optJSONObject("photoAttachment");if(manifest==null)continue;if(l.optLong("revision")==0||l.has("conflict"))continue;String sha=manifest.optString("sha256");if(sha.equals(l.optString("photoDone")))continue;tasks.add(new JSONObject().put("id",project.getString("id")).put("manifest",new JSONObject(manifest.toString())));}}catch(Exception e){return;}if(tasks.isEmpty())return;worker.execute(()->{for(JSONObject task:tasks){try{String id=task.getString("id");JSONObject m=task.getJSONObject("manifest");String sha=m.getString("sha256");File dir=PhotoAttachment.directory(a,new JSONObject().put("id",id)),photo=new File(dir,"approved-"+sha+".jpg");if(!photo.exists())photo=new File(dir,"photo.jpg");boolean local=photo.exists()&&SecureGateway.hash(Files.readAllBytes(photo.toPath())).equals(sha);JSONObject cap=transport.call(local?"/sync/photo-put":"/sync/photo-get",new JSONObject().put("projectId",id).put("sha256",sha).put("size",m.getLong("sizeBytes")));byte[] bytes=local?Files.readAllBytes(photo.toPath()):transport.download(cap.getString("url"));if(bytes.length!=m.getLong("sizeBytes")||!SecureGateway.hash(bytes).equals(sha))throw new IOException("Hash da foto não confere.");if(local)transport.upload(cap.getString("url"),bytes);final boolean hadLocal=local;main.post(()->{if(closed||state.optBoolean("detaching")||state.optString("tenant").isEmpty())return;try{JSONObject target=store.find("projects",id);if(target==null)return;if(!hadLocal&&(target.optJSONObject("photoAttachment")==null||!sha.equals(target.optJSONObject("photoAttachment").optString("sha256"))))return;if(!hadLocal){AtomicFile file=new AtomicFile(new File(PhotoAttachment.directory(a,target),"photo.jpg"));FileOutputStream out=null;try{out=file.startWrite();out.write(bytes);file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}link("projects",id).put("photoDone",sha);state.put("photoPending",false);save();notifyUi();}catch(Exception ignored){}});}catch(Exception e){main.post(()->{if(closed||state.optBoolean("detaching")||state.optString("tenant").isEmpty())return;try{state.put("photoPending",true);save();}catch(Exception ignored){}notifyUi();});}}});}
 void close(){closed=true;main.removeCallbacksAndMessages(null);worker.shutdown();}
}
